// ShipmentScopeTenant restricts a query to a single tenant by adding:
//
//	WHERE sp.organization_id = ? AND sp.business_unit_id = ?
//
// Returns the same *bun.SelectQuery so it can be chained fluently:
//
//	buncolgen.ShipmentScopeTenant(sq, ti).
//		Where(buncolgen.ShipmentColumns.ID.Eq(), id)
func ShipmentScopeTenant(q *bun.SelectQuery, ti pagination.TenantInfo) *bun.SelectQuery {
	return ScopeTenant(q, ShipmentColumns.OrganizationID, ShipmentColumns.BusinessUnitID, ti)
}

// ShipmentScopeTenantUpdate restricts an update query to a single tenant.
// Use this inside UpdateQuery.WhereGroup callbacks:
//
//	WhereGroup(" AND ", func(uq *bun.UpdateQuery) *bun.UpdateQuery {
//		return buncolgen.ShipmentScopeTenantUpdate(uq, req.TenantInfo).
//			Where(buncolgen.ShipmentColumns.ID.In(), bun.List(ids))
//	})
func ShipmentScopeTenantUpdate(q *bun.UpdateQuery, ti pagination.TenantInfo) *bun.UpdateQuery {
	return ScopeTenantUpdate(q, ShipmentColumns.OrganizationID, ShipmentColumns.BusinessUnitID, ti)
}

// ShipmentScopeTenantDelete restricts a delete query to a single tenant.
// Use this inside DeleteQuery.WhereGroup callbacks:
//
//	WhereGroup(" AND ", func(dq *bun.DeleteQuery) *bun.DeleteQuery {
//		return buncolgen.ShipmentScopeTenantDelete(dq, req.TenantInfo).
//			Where(buncolgen.ShipmentColumns.ID.Eq(), id)
//	})
func ShipmentScopeTenantDelete(q *bun.DeleteQuery, ti pagination.TenantInfo) *bun.DeleteQuery {
	return ScopeTenantDelete(q, ShipmentColumns.OrganizationID, ShipmentColumns.BusinessUnitID, ti)
}

// ShipmentApplyTenant returns a closure for SelectQuery.Apply() that scopes to a single tenant.
// Use this instead of wrapping ScopeTenant in an anonymous function:
//
//	q.Apply(buncolgen.ShipmentApplyTenant(tenantInfo))
func ShipmentApplyTenant(ti pagination.TenantInfo) func(*bun.SelectQuery) *bun.SelectQuery {
	return ApplyTenant(ShipmentColumns.OrganizationID, ShipmentColumns.BusinessUnitID, ti)
}

